/* ═══════════════════════════════════════════════════════════════════
   duel-net.js  —  two-phone multiplayer over local WiFi.  v1.2.0

   DO NOT EDIT THIS FILE. Sections 1–4 (helpers, Diag, Sdp, Peer, Qr)
   are the exact code that was debugged against real phones; every line
   in Sdp and Peer is there because something broke without it. Rewriting
   them from memory reintroduces bugs that took a live debugging session
   to find. Build your game on top by calling Duel.start({...}).

   What it does
     · squeezes a WebRTC offer into ~200-300 characters so it fits a QR
     · hands that over as a deep link the stock camera app can open
     · takes the reply code back by in-page scan, paste or share sheet
     · opens two data channels: lossy for state, reliable for commands
     · runs a fixed-step host-authoritative loop with guest prediction
     · logs every ICE event to a panel you can copy out when it fails
     · detects a dropped link four ways, freezes the match and tries an
       ICE restart over the data channel before asking the player
   ═══════════════════════════════════════════════════════════════════ */
(() => {
'use strict';

/* ── 1. helpers ─────────────────────────────────────────────────── */
const $ = s => document.querySelector(s);
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const lerp  = (a, b, k) => a + (b - a) * k;
const r1    = v => Math.round(v * 10) / 10;
const TAU   = Math.PI * 2;
const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;

let toastTimer;
function toast(msg) {
  const el = $('#toast');
  el.textContent = msg; el.classList.add('on');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('on'), 2600);
}

const b64u = {
  enc(bytes) {
    let s = '';
    for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
    return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  },
  dec(str) {
    let s = str.replace(/-/g, '+').replace(/_/g, '/');
    while (s.length % 4) s += '=';
    const raw = atob(s), out = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
    return out;
  },
  encText(t) { return b64u.enc(new TextEncoder().encode(t)); },
  decText(c) { return new TextDecoder().decode(b64u.dec(c)); },
};

const hexToBytes = hex => {
  const h = hex.replace(/[^0-9a-f]/gi, '');
  const out = new Uint8Array(h.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(h.substr(i * 2, 2), 16);
  return out;
};
const bytesToHex = (b, sep = '') =>
  [...b].map(x => x.toString(16).padStart(2, '0').toUpperCase()).join(sep);

/* ── 1b. Diag ────────────────────────────────────────────────────────
   Pairing fails for boring network reasons far more often than for
   protocol reasons, and neither phone will tell you which. So every
   ICE event is written to a panel you can open and copy out.
   ───────────────────────────────────────────────────────────────── */
const Diag = {
  lines: [], t0: performance.now(), open: false, lastPath: '',

  log(msg) {
    const at = ((performance.now() - this.t0) / 1000).toFixed(2).padStart(6);
    this.lines.push(at + 's  ' + msg);
    if (this.lines.length > 400) this.lines.shift();
    console.log('[dohyo]', msg);
    this.render();
  },

  render() {
    if (!this.open) return;
    const pre = $('#diag-log');
    if (!pre) return;
    pre.textContent = this.lines.join('\n');
    pre.scrollTop = pre.scrollHeight;
  },

  toggle(on) {
    this.open = on ?? !this.open;
    $('#diag').classList.toggle('on', this.open);
    this.render();
  },

  /* Wire one peer connection up to the log. */
  attach(pc, who) {
    this.log(`--- ${who} peer created ---`);
    pc.addEventListener('icecandidate', e => {
      if (e.candidate) this.log('local  ' + e.candidate.candidate.replace(/^candidate:/, ''));
      else this.log('local  gathering finished');
    });
    pc.addEventListener('icecandidateerror', e => {
      this.log(`ICE error  ${e.errorCode} ${e.errorText || ''} ${e.url || ''}`);
    });
    pc.addEventListener('iceconnectionstatechange', () => this.log('ice        ' + pc.iceConnectionState));
    pc.addEventListener('icegatheringstatechange', () => this.log('gathering  ' + pc.iceGatheringState));
    pc.addEventListener('connectionstatechange', () => this.log('connection ' + pc.connectionState));
    pc.addEventListener('signalingstatechange', () => this.log('signalling ' + pc.signalingState));

    clearInterval(this._poll);
    this._pollPc = pc;
    this._poll = setInterval(() => this.path(pc), 1500);
  },

  /* The poll belongs to one peer connection; when that peer goes, so
     does it, rather than ticking on until the next attach. */
  detach(pc) {
    if (this._pollPc && this._pollPc !== pc) return;
    clearInterval(this._poll);
    this._poll = 0; this._pollPc = null;
  },

  /* Which pair of addresses actually carried a packet, and how fast. */
  async path(pc) {
    if (!pc || pc.connectionState === 'closed') { clearInterval(this._poll); return; }
    let stats; try { stats = await pc.getStats(); } catch { return; }
    const local = {}, remote = {};
    let pair = null;
    stats.forEach(r => {
      if (r.type === 'local-candidate') local[r.id] = r;
      else if (r.type === 'remote-candidate') remote[r.id] = r;
      else if (r.type === 'candidate-pair' && r.state === 'succeeded' && (r.nominated || r.selected)) pair = r;
    });
    if (!pair) return;
    const l = local[pair.localCandidateId] || {}, r = remote[pair.remoteCandidateId] || {};
    const line = `path  ${l.candidateType} ${l.address}:${l.port}  ->  ` +
                 `${r.candidateType} ${r.address}:${r.port}  ` +
                 `rtt ${Math.round((pair.currentRoundTripTime || 0) * 1000)}ms`;
    if (line !== this.lastPath) { this.lastPath = line; this.log(line); }
  },

  /* Show what the other phone claimed it could be reached on. */
  describeRemote(code, label) {
    try {
      const parts = b64u.decText(code).split(',');
      this.log(`${label} code  ${code.length} chars, ufrag ${parts[0]}, setup ${SETUP[+parts[3]]}`);
      (parts[4] || '').split('&').filter(Boolean).forEach(c => {
        const [addr, port] = c.split('!');
        this.log(`  remote  ${addr[0] === 'h' ? 'host ' : 'srflx'} ${Sdp._unpackAddr(addr.slice(1))}:${port}`);
      });
    } catch { this.log(label + ' code could not be read'); }
  },

  report() { return this.lines.join('\n'); },
};

/* ── 2. Sdp ─────────────────────────────────────────────────────────
   A raw WebRTC offer is ~1.5 kB, far too much for a QR square that a
   phone can read off another phone's screen. Everything in it is either
   fixed boilerplate or derivable, except four fields and the candidate
   list — so we keep only those and rebuild the rest on arrival. The
   result is ~200 characters.
   ───────────────────────────────────────────────────────────────── */
const SETUP = ['actpass', 'active', 'passive'];
const CAND_MAX = 8, CAND_PUB = 3;   // total candidate slots, and slots held for srflx

const Sdp = {
  pack(sdp) {
    const one = re => ((sdp.match(re) || [])[1] || '').trim();
    const ufrag = one(/^a=ice-ufrag:(.*)$/m);
    const pwd   = one(/^a=ice-pwd:(.*)$/m);
    const fp    = one(/^a=fingerprint:sha-256 (.*)$/mi);
    const setup = one(/^a=setup:(.*)$/m);

    const seen = new Set(), found = [];
    for (const m of sdp.matchAll(/^a=candidate:(.*)$/gm)) {
      const f = m[1].trim().split(/\s+/);
      if (f.length < 8) continue;
      if (f[1] !== '1') continue;                        // component: rtp only
      if (f[2].toLowerCase() !== 'udp') continue;        // tcp candidates cannot carry this
      const type = f[7];
      if (type !== 'host' && type !== 'srflx') continue; // no relays: nothing to relay through
      const addr = f[4];
      if (/^169\.254\./.test(addr) || /^fe80:/i.test(addr)) continue;  // link-local, never routable
      const key = addr + ':' + f[5];
      if (seen.has(key)) continue;
      seen.add(key);
      found.push({ type, addr, port: f[5], v6: addr.includes(':') });
    }
    /* Order is the priority the other phone will try them in: the local
       wire first, then IPv6, then whatever a STUN server saw. */
    const rank = c => (c.type === 'host' ? 0 : 2) + (c.v6 ? 1 : 0);
    found.sort((a, b) => rank(a) - rank(b));
    /* The local wire is still tried first — that ordering is the whole point.
       But a phone with several local interfaces used to spend the entire
       budget on host candidates, leaving no srflx in the code at all, and a
       link with no public candidate has nothing to rotate onto when the LAN
       path dies. So hold slots back for them. */
    const hostC = found.filter(c => c.type === 'host');
    const pubC  = found.filter(c => c.type !== 'host');
    const nPub  = Math.min(pubC.length, CAND_PUB);
    const cands = hostC.slice(0, CAND_MAX - nPub).concat(pubC.slice(0, nPub)).map(c =>
      (c.type === 'host' ? 'h' : 's') + Sdp._packAddr(c.addr) + '!' + c.port);

    const payload = [
      ufrag, pwd, b64u.enc(hexToBytes(fp)),
      String(Math.max(0, SETUP.indexOf(setup))),
      cands.join('&'),
    ].join(',');
    return b64u.encText(payload);
  },

  unpack(code) {
    const [ufrag, pwd, fp64, setupIdx, candStr = ''] =
      b64u.decText(code.trim()).split(',');
    if (!ufrag || !pwd || !fp64) throw new Error('That code is not a ring code.');

    const lines = [
      'v=0', 'o=- 0 0 IN IP4 127.0.0.1', 's=-', 't=0 0',
      'a=group:BUNDLE 0', 'a=msid-semantic: WMS',
      'm=application 9 UDP/DTLS/SCTP webrtc-datachannel',
      'c=IN IP4 0.0.0.0',
      'a=ice-ufrag:' + ufrag,
      'a=ice-pwd:' + pwd,
      'a=fingerprint:sha-256 ' + bytesToHex(b64u.dec(fp64), ':'),
      'a=setup:' + (SETUP[+setupIdx] || 'actpass'),
      'a=mid:0', 'a=sctp-port:5000', 'a=max-message-size:262144',
    ];
    candStr.split('&').filter(Boolean).forEach((c, i) => {
      const [tagged, port] = c.split('!');
      const kind = tagged[0] === 's' ? 'srflx' : 'host';
      const addr = Sdp._unpackAddr(tagged.slice(1));
      const rel = kind === 'srflx' ? ' raddr 0.0.0.0 rport 0' : '';
      lines.push(`a=candidate:${i + 1} 1 udp ${2130706431 - i} ` +
                 `${addr} ${port} typ ${kind}${rel} generation 0`);
    });
    /* Everything is in this one code, so say so — otherwise the other
       side waits for candidates that will never arrive. */
    lines.push('a=end-of-candidates');
    return lines.join('\r\n') + '\r\n';
  },

  /* Browsers hide your LAN address behind a random `<uuid>.local` name.
     A uuid is 36 characters of mostly hex, so pack it back to 16 bytes. */
  _packAddr(a) {
    const m = /^([0-9a-f-]{36})\.local$/i.exec(a);
    return m ? '*' + b64u.enc(hexToBytes(m[1])) : a;
  },
  _unpackAddr(a) {
    if (a[0] !== '*') return a;
    const h = bytesToHex(b64u.dec(a.slice(1))).toLowerCase();
    return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}.local`;
  },
};

/* ── 3. Peer ─────────────────────────────────────────────────────────
   Two channels, because the two kinds of traffic want opposite things:
     state — positions, 30 times a second. Late is worse than lost.
     cmd   — "I charged in this direction". Must arrive, exactly once.
   ───────────────────────────────────────────────────────────────── */
const HB_EVERY = 1000;    // how often each side says it is still there
const HB_DEAD  = 3500;    // silence past this and the link is treated as gone
const RC_MIN   = 500, RC_MAX = 8000, RC_WINDOW = 60000;

class Peer {
  constructor(isHost, sid) {
    this.isHost = isHost;
    /* The pairing identity, which outlives any single ICE session. A
       reconnect resumes this match rather than starting a new one, so the
       QR code is scanned once per match and not once per network blip. */
    this.sid = sid || (isHost ? Math.random().toString(36).slice(2, 10) : null);
    this.onready = null; this.onmsg = null; this.onlost = null;
    this.ondrop = null; this.onresume = null; this.ongiveup = null;
    this.state = null; this.cmd = null;

    this.up = false;        // has been fully linked at least once
    this.down = false;      // link considered lost, recovery running
    this.closed = false;
    this.rxAt = performance.now();
    this.tries = 0; this.downAt = 0;
    this._retry = 0; this._beat = 0; this._nego = false;

    /* STUN is used only while pairing, to learn how this phone looks from
       outside in case the two are not on the same subnet. No game traffic
       ever goes near it — once linked, the phones talk directly. */
    this.pc = new RTCPeerConnection({
      iceServers: Peer.stun ? [{ urls: ['stun:stun.l.google.com:19302',
                                        'stun:stun.cloudflare.com:3478'] }] : [],
    });
    Diag.attach(this.pc, isHost ? 'East' : 'West');

    if (isHost) {
      this.state = this.pc.createDataChannel('state', { ordered: false, maxRetransmits: 0 });
      this.cmd   = this.pc.createDataChannel('cmd',   { ordered: true });
      this._wire(this.state); this._wire(this.cmd);
    } else {
      this.pc.ondatachannel = e => { this[e.channel.label] = e.channel; this._wire(e.channel); };
    }

    /* Four independent signals, because on a phone no single one is
       dependable: ICE gives up, the connection gives up, a channel closes,
       or — the nasty one — nothing fires at all and the socket is quietly
       dead while both channels still read `open`. The heartbeat in _watch
       covers that last case. */
    this.pc.oniceconnectionstatechange = () => {
      const s = this.pc.iceConnectionState;
      if (s === 'failed' || s === 'disconnected') this._down('ice ' + s);
      else if (s === 'connected' || s === 'completed') this._maybeUp();
    };
    this.pc.onconnectionstatechange = () => {
      const s = this.pc.connectionState;
      /* Before the match starts this is a pairing failure and belongs to
         the pairing screen; after it, it is a drop and we try to recover. */
      if (s === 'failed' && !this.up) { this.onlost?.(s); return; }
      if (s === 'failed') this._down('connection failed');
      else if (s === 'connected') this._maybeUp();
    };
  }

  _wire(ch) {
    ch.onopen  = () => this._maybeUp();
    ch.onclose = () => this._down('channel closed');
    ch.onerror = () => this._down('channel error');
    ch.onmessage = e => {
      this.rxAt = performance.now();
      let d; try { d = JSON.parse(e.data); } catch { return; }
      if (d.k === '_hb') {          // liveness, and the session id as a backstop
        if (d.s && !this.isHost) this.sid = d.s;
        return;
      }
      if (d.k === '_ro' || d.k === '_ra') return this._answerNego(d);
      if (d.k === '_sid') { this.sid = d.s; return; }
      this.onmsg?.(d);
    };
  }

  /* Any positive signal lands here; it only counts once both channels are
     actually open, which is what `onready` always meant. */
  _maybeUp() {
    if (this.closed) return;
    if (this.state?.readyState !== 'open' || this.cmd?.readyState !== 'open') return;
    const first = !this.up, wasDown = this.down;
    this.up = true; this.down = false;
    this.tries = 0; this.downAt = 0;
    clearTimeout(this._retry); this._retry = 0;
    this._watch();
    if (first) {
      if (this.isHost) this._raw('cmd', { k: '_sid', s: this.sid });
      this.onready?.();
    } else if (wasDown) {
      Diag.log('link restored');
      this.onresume?.();
    }
  }

  /* Everything that says the link is gone funnels through here, debounced,
     because the signals above usually fire together. */
  _down(why) {
    if (this.closed || this.down || !this.up) return;
    this.down = true;
    this.downAt = performance.now();
    this.tries = 0;
    Diag.log('!! link down — ' + why);
    this.ondrop?.(why);
    this._retryLoop();
  }

  /* Exponential backoff with jitter, capped, and with a hard window after
     which we stop burning battery and hand the player a button instead. */
  _retryLoop() {
    if (this.closed || !this.down) return;
    if (performance.now() - this.downAt > RC_WINDOW) {
      Diag.log('!! gave up reconnecting after ' + (RC_WINDOW / 1000) + 's');
      this.ongiveup?.();
      return;
    }
    this.tries++;
    this._recover();
    const back = Math.min(RC_MAX, RC_MIN * Math.pow(2, this.tries - 1));
    clearTimeout(this._retry);
    this._retry = setTimeout(() => this._retryLoop(), back * (0.7 + Math.random() * 0.6));
  }

  /* An ICE restart re-gathers candidates on whatever network this phone is
     on now and re-nominates a pair — which is exactly how a dead LAN path
     rotates onto the public one. The catch is that the new offer has to
     reach the other phone, and the only link between them is the data
     channel. While it is still open this works. Once it has closed there is
     nowhere to put the offer, so the match waits for the player instead. */
  async _recover() {
    try { this.pc.restartIce?.(); } catch {}
    if (!this.isHost) return;                     // host drives, to avoid glare
    if (this.cmd?.readyState !== 'open') return;  // no path to carry the offer
    if (this._nego) return;
    this._nego = true;
    try {
      await this.pc.setLocalDescription(await this.pc.createOffer({ iceRestart: true }));
      this._raw('cmd', { k: '_ro', sdp: this.pc.localDescription.sdp });
      Diag.log('ice restart offered over the data channel');
    } catch (e) { Diag.log('restart offer failed: ' + e.message); }
    this._nego = false;
  }

  /* Renegotiation goes over the channel, where there is no QR budget, so
     the SDP travels whole rather than packed. */
  async _answerNego(d) {
    try {
      if (d.k === '_ro') {
        await this.pc.setRemoteDescription({ type: 'offer', sdp: d.sdp });
        await this.pc.setLocalDescription(await this.pc.createAnswer());
        this._raw('cmd', { k: '_ra', sdp: this.pc.localDescription.sdp });
        Diag.log('ice restart answered');
      } else {
        await this.pc.setRemoteDescription({ type: 'answer', sdp: d.sdp });
        Diag.log('ice restart accepted');
      }
    } catch (e) { Diag.log('renegotiation failed: ' + e.message); }
  }

  /* A data channel can sit at `open` long after the socket under it died —
     no event ever fires, and both phones happily play into the void. So
     each side speaks once a second and treats silence as a drop. */
  _watch() {
    clearInterval(this._beat);
    this._beat = setInterval(() => {
      if (this.closed) return;
      this._raw('cmd', this.isHost ? { k: '_hb', s: this.sid } : { k: '_hb' });
      if (!this.down && performance.now() - this.rxAt > HB_DEAD) this._down('silent channel');
    }, HB_EVERY);
  }

  /* Returning from a backgrounded tab: nothing may have fired while we were
     away, so ask outright rather than trusting readyState. */
  probe() {
    if (this.closed || this.down) return;
    this.rxAt = performance.now();
    this._raw('cmd', { k: '_hb' });
    setTimeout(() => {
      if (!this.closed && !this.down && performance.now() - this.rxAt > HB_DEAD) {
        this._down('no answer after resume');
      }
    }, HB_DEAD + 200);
  }

  /* The manual button, once automatic recovery has given up. */
  retry() {
    if (this.closed) return;
    this.downAt = performance.now(); this.tries = 0;
    if (!this.down) { this.down = true; this.ondrop?.('manual'); }
    this._retryLoop();
  }

  /* Gather every candidate up front so the whole handshake fits in one
     code each way — no trickling, because there is no signalling link. */
  _gathered() {
    return new Promise(done => {
      if (this.pc.iceGatheringState === 'complete') return done();
      const check = () => { if (this.pc.iceGatheringState === 'complete') finish(); };
      const finish = () => {
        clearTimeout(timer);
        this.pc.removeEventListener('icegatheringstatechange', check);
        done();
      };
      const timer = setTimeout(finish, 2400);
      this.pc.addEventListener('icegatheringstatechange', check);
    });
  }

  async makeOffer() {
    await this.pc.setLocalDescription(await this.pc.createOffer());
    await this._gathered();
    const code = Sdp.pack(this.pc.localDescription.sdp);
    Diag.log(`offer built, ${code.length} chars`);
    return code;
  }
  async answerTo(code) {
    Diag.describeRemote(code, 'offer in');
    await this.pc.setRemoteDescription({ type: 'offer', sdp: Sdp.unpack(code) });
    await this.pc.setLocalDescription(await this.pc.createAnswer());
    await this._gathered();
    const out = Sdp.pack(this.pc.localDescription.sdp);
    Diag.log(`answer built, ${out.length} chars`);
    return out;
  }
  async takeAnswer(code) {
    Diag.describeRemote(code, 'answer in');
    await this.pc.setRemoteDescription({ type: 'answer', sdp: Sdp.unpack(code) });
  }
  /* _raw ignores the drop guard — heartbeats and renegotiation have to keep
     flowing while the link is considered down. `send` is the game's door and
     stays shut, so no gameplay traffic is generated during an outage. */
  _raw(label, obj) {
    const ch = this[label];
    if (ch && ch.readyState === 'open') { try { ch.send(JSON.stringify(obj)); } catch {} }
  }
  send(label, obj) { if (!this.down) this._raw(label, obj); }

  /* Everything this peer ever attached is detached here, so repeated
     drop/recover cycles in one match cannot leak timers or listeners. */
  close() {
    if (this.closed) return;
    this.closed = true;
    clearTimeout(this._retry); clearInterval(this._beat);
    this._retry = this._beat = 0;
    for (const ch of [this.state, this.cmd]) {
      if (ch) { ch.onopen = ch.onclose = ch.onerror = ch.onmessage = null; }
    }
    this.pc.oniceconnectionstatechange = null;
    this.pc.onconnectionstatechange = null;
    this.pc.ondatachannel = null;
    Diag.detach(this.pc);
    try { this.pc.close(); } catch {}
  }
}
Peer.stun = true;   /* toggled from the diagnostics panel */

/* ── 4. Qr ──────────────────────────────────────────────────────── */
const Qr = {
  draw(el, text) {
    el.innerHTML = '';
    let q = null;
    for (const type of [0, 8, 10, 12, 14, 16, 20, 25]) {
      try { q = qrcode(type, 'M'); q.addData(text, 'Byte'); q.make(); break; }
      catch { q = null; }
    }
    if (!q) { el.textContent = 'code too long'; return false; }
    el.innerHTML = q.createImgTag(6, 0);
    return true;
  },

  /* Pull a code out of whatever the camera read: our own deep link, or
     the bare code if it was pasted or shared as text. */
  extract(raw) {
    const m = /[#?&](?:o|a)=([A-Za-z0-9_-]+)/.exec(raw || '');
    return (m ? m[1] : String(raw || '').trim()).replace(/\s+/g, '');
  },

  async scan(video, onFound) {
    const stream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: { ideal: 'environment' }, width: { ideal: 1280 } },
      audio: false,
    });
    video.srcObject = stream;
    await video.play().catch(() => {});

    const buf = document.createElement('canvas');
    const bx  = buf.getContext('2d', { willReadFrequently: true });
    let alive = true;
    const halt = () => { alive = false; stream.getTracks().forEach(t => t.stop()); };

    const tick = () => {
      if (!alive) return;
      const vw = video.videoWidth;
      if (vw && video.readyState >= 2) {
        const w = Math.min(680, vw);
        const h = Math.round(video.videoHeight * w / vw);
        buf.width = w; buf.height = h;
        bx.drawImage(video, 0, 0, w, h);
        try {
          const px = bx.getImageData(0, 0, w, h);
          const hit = jsQR(px.data, w, h, { inversionAttempts: 'dontInvert' });
          if (hit?.data) { halt(); onFound(Qr.extract(hit.data)); return; }
        } catch {}
      }
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
    return halt;
  },
};

/* Asking for the camera early has a useful side effect: once a page has
   camera permission the browser stops hiding your LAN address behind a
   `.local` alias, which makes the direct connection much more reliable. */
async function warmCamera() {
  try {
    const s = await navigator.mediaDevices.getUserMedia({ video: true });
    s.getTracks().forEach(t => t.stop());
  } catch {}
}

/* ── 5. Board ────────────────────────────────────────────────────────
   Every game draws into a fixed 1000×1000 world with the origin at the
   centre, so a puck at (0,0) is centred on any screen. The engine owns
   device-pixel-ratio, resizing and shake; a game never touches them.
   ───────────────────────────────────────────────────────────────── */
const Board = {
  ctx: null, cv: null, w: 0, h: 0, dpr: 1, scale: 1, shake: 0, _bound: false,

  attach(canvas) {
    this.cv = canvas; this.ctx = canvas.getContext('2d');
    this.resize();
    if (!this._bound) { this._bound = true; addEventListener('resize', () => this.resize()); }
  },

  resize() {
    const dpr = Math.min(devicePixelRatio || 1, 2.5);
    const w = this.cv.clientWidth, h = this.cv.clientHeight;
    this.cv.width = Math.round(w * dpr); this.cv.height = Math.round(h * dpr);
    this.w = w; this.h = h; this.dpr = dpr;
    this.scale = Math.min(w * 0.97, h * 0.72) / 1000;
  },

  kick(amount) { if (!REDUCED) this.shake = Math.min(26, this.shake + amount); },

  /* screen point -> world point */
  toWorld(cx, cy) {
    const r = this.cv.getBoundingClientRect();
    return { x: (cx - r.left - this.w / 2) / this.scale,
             y: (cy - r.top - this.h / 2) / this.scale };
  },

  frame(dt, paint) {
    const x = this.ctx;
    x.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    x.clearRect(0, 0, this.w, this.h);
    this.shake = Math.max(0, this.shake - dt * 60);
    x.save();
    if (this.shake > 0.2) {
      x.translate((Math.random() - 0.5) * this.shake, (Math.random() - 0.5) * this.shake);
    }
    x.translate(this.w / 2, this.h / 2);
    x.scale(this.scale, this.scale);
    paint(x);
    x.restore();
  },
};

/* ── 5b. Net ─────────────────────────────────────────────────────────
   The only UI the engine owns outright. It is injected rather than added
   to shell.html so an already-built page picks it up unchanged, and it
   reads its colours from the same custom properties as everything else.
   ───────────────────────────────────────────────────────────────── */
const Net = {
  el: null,

  _make() {
    if (this.el) return this.el;
    const st = document.createElement('style');
    st.textContent = '@keyframes netspin{to{transform:rotate(360deg)}}';
    document.head.appendChild(st);

    const d = document.createElement('div');
    d.id = 'netwrap';
    d.setAttribute('role', 'status');
    d.style.cssText =
      'position:fixed;inset:0;z-index:95;display:none;align-items:center;justify-content:center;' +
      'padding:24px;background:rgba(0,0,0,.62);backdrop-filter:blur(3px);' +
      '-webkit-backdrop-filter:blur(3px);font-family:var(--body,system-ui,sans-serif)';
    d.innerHTML =
      '<div style="width:100%;max-width:320px;text-align:center;background:var(--panel,#111);' +
      'border:1px solid rgba(255,255,255,.14);border-radius:16px;padding:26px 22px">' +
      '<div id="net-spin" style="width:30px;height:30px;margin:0 auto 16px;border-radius:50%;' +
      'border:2px solid rgba(255,255,255,.18);border-top-color:var(--accent,#fff);' +
      'animation:netspin .9s linear infinite"></div>' +
      '<b id="net-title" style="display:block;margin-bottom:7px;color:var(--ink,#fff);' +
      'font:600 17px/1.3 var(--display,inherit)"></b>' +
      '<p id="net-note" style="margin:0 0 18px;font-size:13.5px;line-height:1.5;' +
      'color:var(--ink,#fff);opacity:.66"></p>' +
      '<button class="btn" id="net-go" style="display:none;width:100%;margin-bottom:9px"></button>' +
      '<button class="btn ghost" id="net-out" style="width:100%"></button></div>';
    document.body.appendChild(d);

    this.el = d;
    return d;
  },

  show(kind) {
    const m = Runtime.meta || {}, d = this._make();
    const spin = kind === 'wait';
    d.querySelector('#net-spin').style.display = spin ? '' : 'none';
    d.querySelector('#net-title').textContent =
      kind === 'wait' ? (m.netLost || 'Reconnecting…')
      : kind === 'left' ? (m.netLeft || 'The other player left')
      : (m.netGone || 'Lost the other phone');
    d.querySelector('#net-note').textContent =
      kind === 'wait' ? (m.netNote || 'The match is held exactly where it was. Waiting for the other phone…')
      : kind === 'left' ? (m.netLeftNote || 'They closed the match on their side.')
      : (m.netGoneNote || 'The link did not come back on its own. Try again, or leave the match.');
    const go = d.querySelector('#net-go'), out = d.querySelector('#net-out');
    go.style.display = kind === 'gone' ? '' : 'none';
    go.textContent = m.netRetry || 'Try again';
    go.onclick = () => { Runtime.peer?.retry(); this.show('wait'); };
    out.textContent = m.netLeave || 'Leave the match';
    out.onclick = () => Runtime.leave();
    /* A connection card outranks anything the player was being asked. */
    Runtime.asking = false;
    d.style.display = 'flex';
  },

  /* A plain two-way question, reusing the same card. */
  ask(o) {
    const d = this._make();
    d.querySelector('#net-spin').style.display = 'none';
    d.querySelector('#net-title').textContent = o.title;
    d.querySelector('#net-note').textContent = o.note || '';
    const go = d.querySelector('#net-go'), out = d.querySelector('#net-out');
    go.style.display = ''; go.textContent = o.yes;
    out.textContent = o.no;
    go.onclick  = () => { this.hide(); o.onYes?.(); };
    out.onclick = () => { this.hide(); o.onNo?.(); };
    d.style.display = 'flex';
  },

  hide() { if (this.el) this.el.style.display = 'none'; },
};

/* ── 6. Runtime ──────────────────────────────────────────────────────
   The match loop and all the networking glue. The host is the only
   machine that runs the rules; the guest holds a mirror it fills from
   snapshots, predicts its own commands locally so the controls feel
   immediate, and lets the next snapshot correct it.
   ───────────────────────────────────────────────────────────────── */
const Runtime = {
  spec: null, game: null, meta: null,
  mode: null, side: 'host', peer: null,
  state: null, view: null, bot: null,
  snapAt: 0, lag: 0, pingAt: 0, aimAt: 0, netAcc: 0,
  aim: null, peerAim: null, dragMax: 200,
  raf: 0, last: 0, acc: 0, wake: null, bannerKey: '', ended: false,
  /* frozen: the link is down, so nothing advances and nothing is sent.
     epoch:  bumped on every resume; commands carry it so input queued
             during an outage can be told apart from live input. */
  frozen: false, epoch: 0, away: 0, asking: false, _repush: 0,

  /* ── lifecycle ── */
  begin(mode, peer) {
    this.mode = mode; this.peer = peer;
    this.side = mode === 'join' ? 'guest' : 'host';
    this.ended = false; this.aim = null; this.peerAim = null;
    this.bannerKey = ''; this.snapAt = 0; this.lag = 0;
    this.frozen = false; this.epoch = 0; this.away = 0;

    if (mode === 'join') {
      this.state = null;
      this.view = this.game.create();           // shape-compatible placeholder
    } else {
      this.state = this.game.create();
      this.view = this.state;
      this.bot = mode === 'solo' && this.spec.bot ? this.spec.bot : null;
    }

    Screens.show('game');
    Board.attach($('#board'));
    this.dragMax = Math.min(Board.w, Board.h) * 0.27;
    this._bindInput();
    this._keepAwake();

    if (peer) {
      peer.onmsg     = d => this._recv(d);
      peer.ondrop    = why => this.freeze(why);
      peer.onresume  = () => this.thaw();
      peer.ongiveup  = () => Net.show('gone');
    }
    this._bindLife();
    this._bindBack();
    this.last = performance.now(); this.acc = 0;
    cancelAnimationFrame(this.raf);
    this.raf = requestAnimationFrame(t => this._frame(t));

    const hint = $('#hint');
    hint.textContent = this.meta.hint || '';
    hint.style.opacity = '1';
    setTimeout(() => { hint.style.opacity = '0'; }, 7000);
  },

  end() {
    cancelAnimationFrame(this.raf);
    this._unbindInput();
    this._unbindLife();
    this._unbindBack(false);
    Net.hide();
    this.wake?.release?.().catch(() => {});
    this.wake = null;
    this.peer?.close(); this.peer = null;
    this.mode = null; this.frozen = false;
  },

  /* Leaving on purpose: tell the other phone first, so it shows an
     end-of-match screen instead of trying to reconnect to nobody. */
  leave() {
    this.peer?._raw('cmd', { k: '_bye' });
    Screens.home();
  },

  /* ── the link went away ── */
  freeze(why) {
    if (this.frozen || !this.mode) return;
    this.frozen = true;
    Diag.log('match frozen — ' + why);
    Net.show('wait');
  },

  /* Host is the only authority, so on the way back it re-seeds the guest
     from a full snapshot rather than letting a stale mirror carry on.
     The epoch moves with it, which is what invalidates any input the guest
     queued while it was away. */
  thaw() {
    if (!this.frozen) return;
    this.frozen = false;
    this.acc = 0; this.last = performance.now();
    Net.hide();
    if (this.state) {
      this.epoch++;
      const full = this.game.full || this.game.snapshot;
      this.peer?.send('cmd', { k: 'S', e: this.epoch, d: full.call(this.game, this.state) });
      Diag.log('resync sent, epoch ' + this.epoch);
    }
  },

  _peerLeft() {
    this.peer?.close();
    this.frozen = true;
    Net.show('left');
  },

  /* Screen shake, available to the game from step(), apply() and render(). */
  kick(amount) { Board.kick(amount); },

  async _keepAwake() {
    try { this.wake = await navigator.wakeLock?.request('screen'); } catch {}
  },

  /* ── the loop ── */
  _frame(now) {
    const dt = Math.min(0.05, (now - this.last) / 1000);
    this.last = now;
    this.raf = requestAnimationFrame(t => this._frame(t));

    /* While the link is down the match still draws — the players need to
       see the board under the overlay — but nothing advances and nothing
       goes on the wire, so the two phones cannot drift apart in the dark. */
    if (this.frozen) {
      /* nothing */
    } else if (this.state) {
      this.acc += dt;
      const H = 1 / 60;
      let guard = 8;
      while (this.acc >= H && guard--) {
        this.bot?.think(this.state, H);
        this.game.step(this.state, H, this);
        this.acc -= H;
      }
      if (this.peer && (this.netAcc += dt) >= 1 / (this.spec.hz || 30)) {
        this.netAcc = 0;
        this.peer.send('state', { k: 's', d: this.game.snapshot(this.state), lag: this.lag | 0 });
      }
    } else {
      const age = clamp((performance.now() - this.snapAt) / 1000, 0, 0.2);
      this.game.smooth?.(this.view, dt, age, this);
      this._share();
    }

    const r = { w: Board.w, h: Board.h, scale: Board.scale, side: this.side,
                aim: this.aim, peerAim: this.peerAim, dt, kick: a => Board.kick(a) };
    Board.frame(dt, x => this.game.render(x, this.view, r));
    this._hud();
  },

  /* ── inbound ── */
  _recv(d) {
    if (d.k === 's') {                       // guest: authoritative snapshot
      this.game.apply(this.view, d.d, this);
      this.lag = d.lag ?? this.lag;
      this.snapAt = performance.now();
      return;
    }
    if (d.k === 'S') {                       // guest: authoritative re-seed
      this.epoch = d.e || 0;
      const restore = this.game.restore || this.game.apply;
      restore.call(this.game, this.view, d.d, this);
      this.snapAt = performance.now();
      this.frozen = false; Net.hide();
      Diag.log('resynced from host, epoch ' + this.epoch);
      return;
    }
    if (d.k === '_bye') { this._peerLeft(); return; }
    if (d.k === 'x') {                       // host: a command from the guest
      /* Anything stamped with an older epoch was queued during an outage.
         Replaying a burst of stale direction changes would steer a snake
         somewhere the player stopped asking for, so it is dropped. */
      if ((d.e || 0) !== this.epoch) return;
      if (this.state) this.game.command(this.state, 'guest', d.m, this);
      return;
    }
    if (d.k === 'a') { this.peerAim = d.a; this.lag = d.l ?? this.lag; return; }
    if (d.k === 'q') { this.peer.send('state', { k: 'r', t: d.t }); return; }
    if (d.k === 'r') { this.lag = Math.round(performance.now() - d.t); return; }
    if (d.k === 'g') {                       // guest asked for a rematch
      if (this.state) { this.state = this.game.create(); this.view = this.state; this._closeSheet(); }
    }
  },

  /* Guest keeps a round-trip measurement and streams its aim so the host
     can draw the wind-up. Throttled to 20 Hz on the lossy channel. */
  _share() {
    if (!this.peer || this.state) return;
    const now = performance.now();
    if (now - this.aimAt >= 50) {
      this.aimAt = now;
      this.peer.send('state', { k: 'a', a: this.aim, l: this.lag });
    }
    if (now - this.pingAt >= 1000) {
      this.pingAt = now;
      this.peer.send('state', { k: 'q', t: now });
    }
  },

  /* ── input: the engine decides host-vs-guest so games never have to ── */
  dispatch(msg) {
    if (!msg || this.frozen) return;
    if (this.state) { this.game.command(this.state, this.side, msg, this); return; }
    this.game.predict?.(this.view, this.side, msg, this);
    this.peer?.send('cmd', { k: 'x', e: this.epoch, m: msg });
  },

  _bindInput() {
    const cv = $('#board');
    let from = null;

    const at = e => {
      const w = Board.toWorld(e.clientX, e.clientY);
      const dx = from ? e.clientX - from.cx : 0;
      const dy = from ? e.clientY - from.cy : 0;
      return { x: w.x, y: w.y, dx, dy,
               len: Math.hypot(dx, dy),
               pow: clamp(Math.hypot(dx, dy) / this.dragMax, 0, 1) };
    };

    const down = e => {
      from = { cx: e.clientX, cy: e.clientY };
      const p = at(e);
      this.aim = { dx: 0, dy: 0, pow: 0 };
      cv.setPointerCapture?.(e.pointerId);
      this.dispatch(this.game.pointer?.('down', p, this));
    };
    const move = e => {
      if (!from) return;
      const p = at(e);
      this.aim = { dx: p.dx, dy: p.dy, pow: p.pow };
      this.dispatch(this.game.pointer?.('move', p, this));
    };
    const up = e => {
      if (!from) return;
      const p = at(e);
      from = null; this.aim = null;
      this.dispatch(this.game.pointer?.('up', p, this));
    };

    this._io = { cv, down, move, up };
    cv.addEventListener('pointerdown', down);
    cv.addEventListener('pointermove', move);
    cv.addEventListener('pointerup', up);
    cv.addEventListener('pointercancel', up);
    addEventListener('resize', this._io.rs = () => {
      this.dragMax = Math.min(Board.w, Board.h) * 0.27;
    });
  },

  /* Phones suspend tabs. Coming back, the accumulator must not try to
     simulate the missing minute, and the link must be checked rather than
     assumed — a suspended tab very often wakes to a socket that died
     quietly while it was away. */
  _bindLife() {
    const vis = () => {
      if (document.visibilityState === 'hidden') { this.away = Date.now(); return; }
      const gone = Date.now() - (this.away || Date.now());
      this.last = performance.now(); this.acc = 0;
      /* A suspended tab can come back having lost our history entry. */
      if (this._back) this._push();
      if (gone > 1500) {
        Diag.log('resumed after ' + Math.round(gone / 1000) + 's in the background');
        this.peer?.probe();
      }
    };
    /* persisted means the page is going into the back/forward cache and may
       well come back, so it is not a goodbye. */
    const bye = e => { if (!e || !e.persisted) this.peer?._raw('cmd', { k: '_bye' }); };
    this._life = { vis, bye };
    document.addEventListener('visibilitychange', vis);
    addEventListener('pageshow', vis);
    addEventListener('resume', vis);
    addEventListener('pagehide', bye);
  },

  _unbindLife() {
    const L = this._life; if (!L) return;
    document.removeEventListener('visibilitychange', L.vis);
    removeEventListener('pageshow', L.vis);
    removeEventListener('resume', L.vis);
    removeEventListener('pagehide', L.bye);
    this._life = null;
  },

  /* One history entry stands between the match and wherever the player came
     from, so the first back press is ours to catch rather than the
     browser's. Only the match screen is guarded; the lobby is untouched. */
  _bindBack() {
    if (this._back) return;
    const W = () => this.meta.backWindow || 3000;
    this._push();
    let armed = 0, reset = 0;

    const pop = () => {
      if (!this.mode) return;
      /* The browser has just eaten our sentinel, so put it back before
         anything else — otherwise the next press leaves the document.
         It goes through a timeout on purpose: a pushState issued inside
         the popstate dispatch is silently dropped on some mobile builds,
         which is exactly how the guard used to disappear after one press. */
      clearTimeout(this._repush);
      this._repush = setTimeout(() => this._push(), 0);

      if (this.asking) return;                 // the dialog already has the floor

      if (armed && Date.now() - armed < W()) {
        /* Second press inside the window: ask outright rather than acting. */
        armed = 0; clearTimeout(reset); reset = 0;
        this.asking = true;
        Net.ask({
          title: this.meta.backAsk || 'Leave the match?',
          note:  this.meta.backAskNote || 'The other player will be told that you left.',
          yes:   this.meta.backAskYes || 'Leave',
          no:    this.meta.backAskNo || 'Keep playing',
          onYes: () => { this.asking = false; this._unbindBack(false); this.leave(); },
          onNo:  () => { this.asking = false; },
        });
        return;
      }

      /* A first press, or one that arrived after the window lapsed — which
         is simply a first press again. Never an exit on its own. */
      armed = Date.now();
      clearTimeout(reset);
      reset = setTimeout(() => { armed = 0; }, W());
      toast(this.meta.backWarn || 'Press back again to leave the game');
    };

    this._back = pop;
    this._backStop = () => { clearTimeout(reset); clearTimeout(this._repush); };
    addEventListener('popstate', pop);
  },

  /* One sentinel, and never two — a stack that grows by one per press would
     take as many presses to unwind as the player made. */
  _push() {
    if (history.state && history.state.duel) return;
    try { history.pushState({ duel: 1 }, '', location.href); } catch {}
  },

  _unbindBack(consumed) {
    if (!this._back) return;
    removeEventListener('popstate', this._back);
    this._back = null;
    this._backStop?.(); this._backStop = null;
    this.asking = false;
    /* Leaving any other way still owes the stack the entry we pushed. */
    if (!consumed && history.state && history.state.duel) history.back();
  },

  _unbindInput() {
    const io = this._io; if (!io) return;
    io.cv.removeEventListener('pointerdown', io.down);
    io.cv.removeEventListener('pointermove', io.move);
    io.cv.removeEventListener('pointerup', io.up);
    io.cv.removeEventListener('pointercancel', io.up);
    removeEventListener('resize', io.rs);
    this._io = null;
  },

  /* ── HUD, driven entirely by what the game reports ── */
  _hud() {
    const st = this.game.status(this.view, this.side, this) || {};

    for (const role of ['host', 'guest']) {
      const box = $('#pips-' + role), pips = (st[role] && st[role].pips) || [];
      if (box.childElementCount !== pips.length) box.innerHTML = '<i></i>'.repeat(pips.length);
      [...box.children].forEach((n, i) => n.classList.toggle('won', !!pips[i]));
      $('#who-' + role).classList.toggle('me', this.side === role);
    }
    $('#clock').textContent = st.clock || '';
    $('#lag').textContent = this.mode === 'solo' ? (this.meta.soloTag || 'practice')
                          : (this.lag ? this.lag + ' ms' : 'linked');

    const b = st.banner, key = st.key || (b ? b.text : '');
    if (key !== this.bannerKey) {
      this.bannerKey = key;
      const el = $('#call');
      el.innerHTML = b ? `<b style="color:${b.color || 'inherit'}">${b.text}</b>` +
                         (b.sub ? `<small>${b.sub}</small>` : '') : '';
      el.classList.remove('pop');
      if (b) { void el.offsetWidth; el.classList.add('pop'); }
    }

    if (st.done && !this.ended) {
      this.ended = true;
      $('#sheet-title').textContent = st.done.title;
      $('#sheet-title').style.color = st.done.color || 'inherit';
      $('#sheet-note').textContent = st.done.note || '';
      $('#again').textContent = this.state ? (this.meta.againHost || 'Play again')
                                           : (this.meta.againGuest || 'Ask for another');
      $('#sheet').classList.add('on');
    } else if (!st.done && this.ended) {
      this.ended = false; this._closeSheet();
    }
  },

  _closeSheet() { this.ended = false; $('#sheet').classList.remove('on'); },

  again() {
    if (this.state) { this.state = this.game.create(); this.view = this.state; this._closeSheet(); }
    else { this.peer?.send('cmd', { k: 'g' }); toast(this.meta.rematchAsk || 'Asked for another'); }
  },
};


/* ── 6b. track ───────────────────────────────────────────────────────
   Following an authoritative point is the one piece of netcode every
   game on this engine needs and almost every game gets subtly wrong, so
   it lives here rather than in each game.

   Two things happen at once: the target is carried forward on its last
   known velocity to cover the gap since the snapshot, and the local copy
   eases onto it. A fixed easing rate is the usual mistake — it looks
   smooth when nothing is happening and rubber-bands badly the moment
   something collides, because the target jumps further than the easing
   can cover. So the rate rises with the size of the error, and past
   `snapAt` it stops easing and simply agrees with the host.
   ───────────────────────────────────────────────────────────────── */
function track(p, to, age, ease = 0.3, snapAt = 90) {
  if (!to) return 0;
  const tx = to.x + (to.vx || 0) * age;
  const ty = to.y + (to.vy || 0) * age;
  const err = Math.hypot(tx - p.x, ty - p.y);
  const k = err >= snapAt ? 1 : Math.min(1, ease + (err / snapAt) * (1 - ease));
  p.x += (tx - p.x) * k;
  p.y += (ty - p.y) * k;
  if ('vx' in to) { p.vx = to.vx; p.vy = to.vy; }
  return err;
}

/* ── 7. Screens ──────────────────────────────────────────────────────
   The pairing flow. This is the part that was hard to get right, so it
   is identical for every game: offer code -> deep link -> reply code.
   ───────────────────────────────────────────────────────────────── */
const Screens = {
  peer: null, stopScan: null, ambientRaf: 0, meta: null, spec: null,

  boot(spec) {
    this.spec = spec; this.meta = spec.meta;
    Runtime.spec = spec; Runtime.game = spec.game; Runtime.meta = spec.meta;

    this._paint();

    $('#go-host').onclick = () => this.host();
    $('#go-join').onclick = () => this.join();
    $('#go-solo').onclick = () => { this.stopAmbient(); Runtime.begin('solo', null); };
    document.querySelectorAll('[data-back]').forEach(b => b.onclick = () => this.home());
    $('#quit').onclick = () => this.home();
    $('#again').onclick = () => Runtime.again();

    $('#use-offer').onclick = () => {
      const c = Qr.extract($('#paste-offer').value);
      c ? this.consumeOffer(c) : toast('Paste the invite code first');
    };
    $('#use-answer').onclick = () => {
      const c = Qr.extract($('#paste-answer').value);
      c ? this.consumeAnswer(c) : toast('Paste their reply code first');
    };
    $('#scan-answer').onclick = () => this.scanAnswer();
    $('#share-answer').onclick = () => this.shareAnswer();

    document.querySelectorAll('[data-diag]').forEach(b => b.onclick = () => Diag.toggle());
    $('#diag-close').onclick = () => Diag.toggle(false);
    $('#diag-stun').onclick = e => {
      Peer.stun = !Peer.stun;
      e.target.textContent = 'STUN ' + (Peer.stun ? 'on' : 'off');
      Diag.log('STUN turned ' + (Peer.stun ? 'on' : 'off') + ' — reopen to apply');
    };
    $('#diag-copy').onclick = async () => {
      try { await navigator.clipboard.writeText(Diag.report()); toast('Report copied'); }
      catch { toast('Select the text and copy it by hand'); }
    };

    if (this.spec.ambient !== false) this.ambient();

    const deep = /[#?&]o=([A-Za-z0-9_-]+)/.exec(location.hash + location.search);
    if (deep) { history.replaceState(null, '', location.pathname); this.join(deep[1]); }
  },

  /* Push the game's identity into the shell. */
  _paint() {
    const m = this.meta, root = document.documentElement;
    if (m.fonts) {
      const l = document.createElement('link');
      l.rel = 'stylesheet'; l.href = m.fonts;
      document.head.appendChild(l);
    }
    for (const [k, v] of Object.entries(m.theme || {})) root.style.setProperty('--' + k, v);
    for (const [k, v] of Object.entries(m.type || {})) root.style.setProperty('--' + k, v);
    root.style.setProperty('--host', m.roles.host.color);
    root.style.setProperty('--guest', m.roles.guest.color);

    document.title = m.title.replace('|', '') + (m.subtitle ? ' — ' + m.subtitle : '');
    const [a, b = ''] = m.title.split('|');
    $('#wordmark').innerHTML = a + (b ? `<span class="accent">${b}</span>` : '');
    $('#eyebrow').textContent = m.eyebrow || 'Local WiFi · peer to peer · no accounts';
    $('#tagline').textContent = m.tagline || '';
    $('#foot').textContent = m.foot ||
      'Both phones need the same WiFi. Once linked, nothing goes through a server — ' +
      'the phones talk straight to each other.';

    for (const role of ['host', 'guest']) {
      const r = m.roles[role];
      $('#mark-' + role).textContent = r.mark || '';
      $('#lbl-' + role).textContent = r.invite || (role === 'host' ? 'Start a game' : 'Join a game');
      $('#sub-' + role).textContent = r.blurb || ('you play as ' + r.name);
      $('#side-' + role).textContent = r.name + (r.mark ? ' ' + r.mark : '');
      $('#who-' + role).textContent = r.name + (r.mark ? ' ' + r.mark : '');
    }
    $('#lbl-solo').textContent = m.solo || 'Practice alone';
    $('#sub-solo').textContent = m.soloBlurb || 'no second phone needed';
    $('#go-solo').style.display = this.spec.bot ? '' : 'none';

    const ol = $('#steps-list');
    ol.innerHTML = (m.steps || [
      ['One of you starts a game', 'A square code appears on that phone.'],
      ['The other points their camera at it', "Your phone's normal camera app works — tap the link."],
      ['Show the reply code back', 'The first phone scans it, and you are in.'],
    ]).map(([t, d], i) =>
      `<li><span class="n">${String(i + 1).padStart(2, '0')}</span><span><b>${t}</b>${d}</span></li>`
    ).join('');
  },

  show(id) {
    document.querySelectorAll('.screen').forEach(s => s.classList.toggle('on', s.id === id));
  },

  home() {
    this.stopScan?.(); this.stopScan = null;
    Runtime.end();
    this.peer?.close(); this.peer = null;
    $('#sheet').classList.remove('on');
    $('#paste-offer').value = ''; $('#paste-answer').value = '';
    $('#join-scan').style.display = ''; $('#join-reply').style.display = 'none';
    $('#host-status').lastElementChild.textContent = 'Waiting for the other phone';
    this.show('lobby');
    if (this.spec.ambient !== false) this.ambient();
  },

  _failed() {
    if (Runtime.mode) return;
    Diag.log('!! no candidate pair worked');
    const st = $('#host-status');
    if (st) st.lastElementChild.textContent = 'Could not reach the other phone';
    toast('No route between the phones — open diagnostics');
  },

  _link(param, code) {
    return `${location.href.split('#')[0].split('?')[0]}#${param}=${code}`;
  },

  async host() {
    this.stopAmbient();
    this.show('host');
    $('#qr-offer').textContent = 'preparing…';
    await warmCamera();

    this.peer?.close();
    this.peer = new Peer(true);
    this.peer.onready = () => { this.stopScan?.(); Runtime.begin('host', this.peer); };
    this.peer.onlost = () => this._failed();

    try {
      const link = this._link('o', await this.peer.makeOffer());
      if (!Qr.draw($('#qr-offer'), link)) this._fallbackText('#qr-offer', link);
      $('#host-status').lastElementChild.textContent = 'Waiting for the other phone to reply';
    } catch (err) {
      toast('Could not start: ' + err.message);
      this.home();
    }
  },

  _fallbackText(sel, text) {
    $(sel).innerHTML =
      `<textarea readonly style="width:230px;height:120px;font:11px monospace">${text}</textarea>`;
  },

  async scanAnswer() {
    try {
      $('#scan-answer').textContent = 'Point at their reply code…';
      const wrap = $('#qr-offer').parentElement;
      wrap.style.display = 'none';
      const holder = document.createElement('div');
      holder.className = 'cam';
      holder.innerHTML = '<video playsinline muted></video><div class="frame"></div>';
      wrap.parentElement.insertBefore(holder, wrap);
      this.stopScan = await Qr.scan(holder.querySelector('video'), code => {
        holder.remove(); wrap.style.display = '';
        $('#scan-answer').textContent = 'Scan their reply code';
        this.consumeAnswer(code);
      });
    } catch {
      $('#scan-answer').textContent = 'Scan their reply code';
      toast('No camera here — paste the code instead');
    }
  },

  async consumeAnswer(code) {
    try {
      $('#host-status').lastElementChild.textContent = 'Linking…';
      await this.peer.takeAnswer(code);
    } catch (err) {
      toast('That reply code did not fit: ' + err.message);
      $('#host-status').lastElementChild.textContent = 'Waiting for the other phone to reply';
    }
  },

  async join(code) {
    this.stopAmbient();
    this.show('join');
    $('#join-scan').style.display = ''; $('#join-reply').style.display = 'none';

    this.peer?.close();
    this.peer = new Peer(false);
    this.peer.onready = () => Runtime.begin('join', this.peer);
    this.peer.onlost = () => this._failed();

    if (code) return this.consumeOffer(code);
    try { this.stopScan = await Qr.scan($('#cam-v'), c => this.consumeOffer(c)); }
    catch { toast('No camera here — paste the invite code instead'); }
  },

  async consumeOffer(code) {
    try {
      this.stopScan?.(); this.stopScan = null;
      await warmCamera();
      const answer = await this.peer.answerTo(code);
      this.answerCode = answer;
      $('#join-scan').style.display = 'none';
      $('#join-reply').style.display = '';
      if (!Qr.draw($('#qr-answer'), answer)) this._fallbackText('#qr-answer', answer);
    } catch (err) {
      toast('That invite code did not fit: ' + err.message);
    }
  },

  async shareAnswer() {
    const text = this.answerCode || '';
    try {
      if (navigator.share) { await navigator.share({ text }); return; }
      await navigator.clipboard.writeText(text);
      toast('Reply code copied — send it to them');
    } catch { toast('Copy failed, read it out instead'); }
  },

  /* Lobby ambience. A game may replace it via spec.ambient(ctx, t, size). */
  ambient() {
    const cv = $('#ambient'); if (!cv) return;
    const ctx = cv.getContext('2d');
    const custom = typeof this.spec.ambient === 'function' ? this.spec.ambient : null;
    let last = performance.now(), t = 0;

    const frame = now => {
      const dt = Math.min(0.04, (now - last) / 1000); last = now; t += dt;
      const dpr = Math.min(devicePixelRatio || 1, 2);
      const w = cv.clientWidth, h = cv.clientHeight;
      if (w && h) {
        cv.width = w * dpr; cv.height = h * dpr;
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.clearRect(0, 0, w, h);
        if (custom) custom(ctx, t, dt, w, h, REDUCED);
      }
      this.ambientRaf = requestAnimationFrame(frame);
    };
    cancelAnimationFrame(this.ambientRaf);
    this.ambientRaf = requestAnimationFrame(frame);
  },

  stopAmbient() { cancelAnimationFrame(this.ambientRaf); this.ambientRaf = 0; },
};

/* ── 8. public entry ─────────────────────────────────────────────── */
const Duel = {
  version: '1.2.0',
  Board, Sdp, Peer, Qr, Diag, Net, Runtime, toast, track, clamp, lerp, r1, TAU, REDUCED,
  start(spec) {
    const need = ['create', 'step', 'snapshot', 'apply', 'command', 'render', 'status'];
    const missing = need.filter(k => typeof spec.game?.[k] !== 'function');
    if (missing.length) throw new Error('game is missing: ' + missing.join(', '));
    const go = () => Screens.boot(spec);
    if (document.readyState === 'loading') addEventListener('DOMContentLoaded', go);
    else go();
  },
};
window.Duel = Duel;
document.addEventListener('gesturestart', e => e.preventDefault());

})();
